教材只用到两种数据类型：有序链表和队列，其数据元素类型定义如下。

```c
typedef struct {
    int OccurTime;    // 事件发生时刻
    int NType;        // 事件类型，0 表示到达事件，1 至 4 表示四个窗口的离开事件
} Event, ElemType;    // 事件类型，有序链表 LinkList 的数据元素类型

typedef LinkList EventList;    // 事件链表类型，定义为有序链表

typedef struct {
    int ArrivalTime;    // 到达时刻
    int Duration;       // 办理事务所需时间
} QElemType;            // 队列的数据元素类型
```

事件元素只带“何时发生”和“是哪种事件”，客户元素只带“何时到达”和“要办多久”，两类信息各司其职。

教材给出的实现把初始化、两个处理器和主循环分开。

```c
void OpenForDay() {
    TotalTime = 0;  CustomerNum = 0;          // 累计时间与客户数清零
    InitList(ev);                              // 事件表置空
    en.OccurTime = 0;  en.NType = 0;           // 第一个客户到达事件
    OrderInsert(ev, en, cmp);                  // 按时刻插入事件表
    for (i = 1; i <= 4; ++i) InitQueue(q[i]);  // 四个队列置空
}

void CustomerArrived() {
    ++CustomerNum;
    Random(durtime, intertime);
    t = en.OccurTime + intertime;              // 下一客户到达时刻
    if (t < CloseTime) OrderInsert(ev, (t, 0), cmp);
    i = Minimum(q);                            // 长度最短的队列
    EnQueue(q[i], (en.OccurTime, durtime));
    if (QueueLength(q[i]) == 1)
        OrderInsert(ev, (en.OccurTime + durtime, i), cmp);
}

void CustomerDeparture() {
    i = en.NType;  DelQueue(q[i], customer);   // 删除第 i 队列的队头
    TotalTime += en.OccurTime - customer.ArrivalTime;
    if (!QueueEmpty(q[i])) {
        GetHead(q[i], customer);
        OrderInsert(ev, (en.OccurTime + customer.Duration, i), cmp);
    }
}

void Bank_Simulation(int CloseTime) {
    OpenForDay();
    while (!ListEmpty(ev)) {
        DelFirst(GetHead(ev), p);  en = GetCurElem(p);
        if (en.NType == 0) CustomerArrived();
        else CustomerDeparture();
    }
    printf("The Average Time is %f\n", (float)TotalTime / CustomerNum);
}
```
